import { defineConfig } from 'astro/config';
import react from '@astrojs/react';

/**
 * Geodesia — static, pre-rendered site.
 *
 * Output: `static` → every route is emitted as finished HTML at build time, so
 * search crawlers receive full semantic content without executing JavaScript.
 * React islands hydrate only the instruments.
 *
 * The sitemap is generated by `src/pages/sitemap.xml.ts` from the same route
 * table the navigation uses (single `/sitemap.xml`, referenced by robots.txt).
 */
const SITE = 'https://geodesia.online';

export default defineConfig({
  site: SITE,
  output: 'static',
  trailingSlash: 'never',
  compressHTML: true,
  devToolbar: { enabled: false },
  integrations: [react()],
  build: {
    inlineStylesheets: 'always',
    assets: '_assets',
  },
  vite: {
    build: {
      cssMinify: 'lightningcss',
      assetsInlineLimit: 2048,
    },
  },
});
